# Debugging the process step by step
# Ensure all directories are clean
import shutil

# Clean up extracted and corrected directories
if os.path.exists(extracted_dir):
    shutil.rmtree(extracted_dir)
os.makedirs(extracted_dir)

if os.path.exists(corrected_dir):
    shutil.rmtree(corrected_dir)
os.makedirs(corrected_dir)

# Step 1: Re-extract files from all zips
for zip_file in zip_files:
    try:
        with zipfile.ZipFile(zip_file, 'r') as archive:
            archive.extractall(extracted_dir)
    except Exception as e:
        print(f"Error extracting {zip_file}: {e}")

# Step 2: Correct spelling and save corrected files
for root, dirs, files in os.walk(extracted_dir):
    for file in files:
        file_path = os.path.join(root, file)
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            corrected_content = spell_check_with_textblob(content)
            corrected_file_path = os.path.join(corrected_dir, file)
            with open(corrected_file_path, 'w', encoding='utf-8') as f:
                f.write(corrected_content)
        except Exception as e:
            print(f"Error processing {file_path}: {e}")

# Step 3: Re-archive the corrected files
try:
    corrected_archive_path = "/mnt/data/CorrectedConversations.zip"
    with zipfile.ZipFile(corrected_archive_path, 'w') as archive:
        for root, dirs, files in os.walk(corrected_dir):
            for file in files:
                file_path = os.path.join(root, file)
                archive.write(file_path, os.path.relpath(file_path, corrected_dir))
except Exception as e:
    print(f"Error creating corrected archive: {e}")

corrected_archive_path

# Log files and attempt to read them
file_log = []

# Log and check content type
for root, dirs, files in os.walk(extracted_dir):
    for file in files:
        file_path = os.path.join(root, file)
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            file_log.append((file_path, "Readable"))
        except Exception as e:
            file_log.append((file_path, f"Unreadable: {e}"))

file_log

# Re-archive the extracted content for manual review
extracted_archive_path = "/mnt/data/ExtractedConversations.zip"
try:
    with zipfile.ZipFile(extracted_archive_path, 'w') as archive:
        for root, dirs, files in os.walk(extracted_dir):
            for file in files:
                file_path = os.path.join(root, file)
                archive.write(file_path, os.path.relpath(file_path, extracted_dir))
except Exception as e:
    extracted_archive_path = str(e)

extracted_archive_path
